import math

def prime_factorization(n):
    """Returns the smallest prime factor, or n if n is prime, or None if n <= 1."""
    if n <= 1:
        return None
    d = 2
    while d * d <= n:
        if n % d == 0:
            return d
        d += 1
    return n

def check_prime_power(n):
    """
    Checks if n is a power of a prime p, and returns (p, exponent) if it is, else (None, None).
    Requires n >= 4 since we need exponent >= 2.
    """
    if n < 4:
        return (None, None)

    # Find the smallest prime factor p
    p = prime_factorization(n)
    if p is None: # Should not happen for n >= 4
        return (None, None)

    # Check if n is purely a power of p
    exponent = 0
    temp = n
    while temp > 1 and temp % p == 0:
        temp //= p
        exponent += 1

    if temp == 1:
        return (p, exponent)
    else:
        return (None, None)

def solve_brute_force(M_max, N_max):
    solutions = []
    print(f"Starting brute force search for 1 <= m, n <= {M_max}")

    for m in range(1, M_max + 1):
        for n in range(1, N_max + 1):
            S1 = m*m + n
            S2 = m + n*n

            # Check if S1 and S2 are prime powers
            p1, A = check_prime_power(S1)
            p2, B = check_prime_power(S2)

            # Check conditions:
            # 1. Both S1 and S2 must be powers of a prime p.
            # 2. The prime p must be the same for both.
            # 3. The exponents A and B must be > 1 (A >= 2 and B >= 2).

            if p1 is not None and p2 is not None and p1 == p2:
                p = p1
                A = min(A, 2) # Only check if A >= 2 and B >= 2
                B = min(B, 2)

                if A >= 2 and B >= 2:
                    solutions.append((m, n, p))

    return solutions

# Set the maximum search bounds as requested
M_MAX = 20
N_MAX = 20
solutions_found = solve_brute_force(M_MAX, N_MAX)

print("\\n--- Solutions Found ---")
if solutions_found:
    print(f"Total solutions found: {len(solutions_found)}")
    for sol in solutions_found:
        print(sol)
else:
    print("No new solutions found.")
